function safeNode(name) {
  try {
    const item = $(name).first();
    if (!item) return { status: 'unavailable', reason: 'empty', data: null };
    const j = item.json ?? {};
    if (j.error || j.message === 'Error' || (typeof j.statusCode === 'number' && j.statusCode >= 400)) {
      return { status: 'unavailable', reason: j.error?.message || j.message || 'http_error', data: null };
    }
    // neverError may put body under data
    const body = j.data && typeof j.data === 'object' && !Array.isArray(j.data) && (j.statusCode || j.headers)
      ? j.data
      : j;
    if (body && body.error && !body.hostname && !body.filesystems && !body.containers && !body.healthy && body.device_present === undefined) {
      return { status: 'unavailable', reason: String(body.error), data: null };
    }
    return { status: 'available', reason: null, data: body };
  } catch (e) {
    return { status: 'unavailable', reason: String(e.message || e), data: null };
  }
}

function round1(n) {
  const x = Number(n);
  return Number.isFinite(x) ? Math.round(x * 10) / 10 : null;
}

const now = new Date();
const toIso = now.toISOString();
const from = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();

const systemSrc = safeNode('Get System Health');
const storageSrc = safeNode('Get Storage Health');
const diskSrc = safeNode('Get Disk Capacity');
const dockerSrc = safeNode('Get Docker Health');
const backupSrc = safeNode('Get Backup Health');

let eventsRaw = [];
try {
  eventsRaw = $('Get Last 24h Events').all().map((i) => i.json).filter(Boolean);
  // Postgres dummy empty row when no events may still return one empty object
  if (eventsRaw.length === 1 && eventsRaw[0].event == null && eventsRaw[0].severity == null) {
    eventsRaw = [];
  }
} catch (e) {
  eventsRaw = null;
}

const eventsAvailable = Array.isArray(eventsRaw);
const eventsList = eventsAvailable ? eventsRaw : [];

const sevCount = { info: 0, warning: 0, error: 0, critical: 0 };
let requiresAttention = 0;
for (const e of eventsList) {
  const s = String(e.severity || 'info').toLowerCase();
  if (sevCount[s] !== undefined) sevCount[s] += 1;
  else sevCount.info += 1;
  if (e.requires_attention === true || e.requires_attention === 't' || e.requires_attention === 'true') {
    requiresAttention += 1;
  }
}

const rank = { critical: 1, error: 2, warning: 3, info: 4 };
const sorted = [...eventsList].sort((a, b) => {
  const ra = rank[String(a.severity || 'info').toLowerCase()] ?? 9;
  const rb = rank[String(b.severity || 'info').toLowerCase()] ?? 9;
  if (ra !== rb) return ra - rb;
  return String(b.created_at || '').localeCompare(String(a.created_at || ''));
});

const topEvents = sorted.slice(0, 8).map((e) => ({
  source: e.source ?? null,
  component: e.component ?? null,
  event: e.event ?? null,
  severity: e.severity ?? null,
  status: e.status ?? null,
  message: e.message ?? null,
  requires_attention: e.requires_attention === true || e.requires_attention === 't' || e.requires_attention === 'true',
  created_at: e.created_at ?? e.timestamp ?? null,
}));

// ---- normalize sections ----
const system = systemSrc.status === 'available'
  ? {
      status: 'available',
      hostname: systemSrc.data.hostname ?? null,
      uptime_seconds: systemSrc.data.uptime_seconds ?? null,
      uptime_human: systemSrc.data.uptime_human ?? null,
      cpu_percent: systemSrc.data.cpu?.usage_percent ?? null,
      load_1m: round1(systemSrc.data.cpu?.load_1m),
      load_5m: round1(systemSrc.data.cpu?.load_5m),
      load_15m: round1(systemSrc.data.cpu?.load_15m),
      ram_percent: systemSrc.data.memory?.used_percent ?? null,
      ram_used_bytes: systemSrc.data.memory?.used_bytes ?? null,
      ram_total_bytes: systemSrc.data.memory?.total_bytes ?? null,
    }
  : { status: 'unavailable', reason: systemSrc.reason };

const storage = storageSrc.status === 'available'
  ? {
      status: 'available',
      healthy: storageSrc.data.healthy === true,
      device_present: storageSrc.data.device_present === true,
      mounted: storageSrc.data.mounted === true,
      mode: storageSrc.data.mode ?? null,
      filesystem: storageSrc.data.filesystem ?? null,
      device: storageSrc.data.device ?? null,
      mountpoint: storageSrc.data.mountpoint ?? null,
      identity_match: storageSrc.data.identity_match === true,
      used_percent: storageSrc.data.used_percent ?? null,
      kernel_errors: storageSrc.data.kernel_errors ?? null,
      emergency_ro: storageSrc.data.emergency_ro === true,
    }
  : { status: 'unavailable', reason: storageSrc.reason };

const disk_capacity = diskSrc.status === 'available'
  ? {
      status: 'available',
      thresholds: diskSrc.data.thresholds ?? null,
      worst_capacity_state: diskSrc.data.summary?.worst_capacity_state ?? null,
      filesystems: (diskSrc.data.filesystems || []).map((fs) => ({
        mount: fs.mount,
        used_percent: fs.used_percent,
        free_gb: fs.free_gb,
        total_gb: fs.total_gb,
        capacity_state: fs.capacity_state,
        available: fs.available !== false,
      })),
    }
  : { status: 'unavailable', reason: diskSrc.reason };

const docker = dockerSrc.status === 'available'
  ? {
      status: 'available',
      healthy: dockerSrc.data.healthy === true,
      summary: dockerSrc.data.summary ?? null,
      critical_problems: (dockerSrc.data.containers || [])
        .filter((c) => c.expected === true && c.ok !== true && String(c.criticality).toLowerCase() === 'critical')
        .map((c) => ({ name: c.name, state: c.state, health: c.health })),
      problem_containers: (dockerSrc.data.containers || [])
        .filter((c) => c.expected === true && c.ok !== true)
        .map((c) => ({ name: c.name, state: c.state, health: c.health, criticality: c.criticality })),
    }
  : { status: 'unavailable', reason: dockerSrc.reason };

const backups = backupSrc.status === 'available'
  ? {
      status: 'available',
      healthy: backupSrc.data.healthy === true,
      checked_at: backupSrc.data.checked_at ?? null,
      postgres: backupSrc.data.postgres ?? null,
      restic: backupSrc.data.restic ?? null,
      offsite: backupSrc.data.offsite ?? null,
      issues: backupSrc.data.issues ?? [],
    }
  : { status: 'unavailable', reason: backupSrc.reason };

// Postgres from docker inventory
let postgres = { status: 'unavailable', reason: 'docker_unavailable' };
if (dockerSrc.status === 'available') {
  const pg = (dockerSrc.data.containers || []).find((c) => c.name === 'postgres');
  if (pg) {
    postgres = {
      status: 'available',
      container: pg.name,
      state: pg.state,
      health: pg.health,
      ok: pg.ok === true,
      criticality: pg.criticality ?? null,
    };
  } else {
    postgres = { status: 'unavailable', reason: 'postgres_container_not_found' };
  }
}

// Services from uptime_kuma events (safe, read-only)
const serviceEvents = eventsList.filter((e) => e.source === 'uptime_kuma');
const services = eventsAvailable
  ? {
      status: 'available',
      source: 'hestia_events',
      down_24h: serviceEvents.filter((e) => e.event === 'service_down').length,
      recovered_24h: serviceEvents.filter((e) => e.event === 'service_recovered').length,
      note: 'Disponibilidade derivada dos eventos Uptime Kuma nas últimas 24h (sem API externa).',
    }
  : { status: 'unavailable', reason: 'events_unavailable' };

const internet = {
  status: 'not_monitored',
  message: 'Internet Watch não faz parte deste relatório.',
};

const events = eventsAvailable
  ? {
      status: 'available',
      total: eventsList.length,
      info: sevCount.info,
      warning: sevCount.warning,
      error: sevCount.error,
      critical: sevCount.critical,
      requires_attention: requiresAttention,
      top_events: topEvents,
    }
  : { status: 'unavailable', reason: 'query_failed', total: 0, info: 0, warning: 0, error: 0, critical: 0, requires_attention: 0, top_events: [] };

// ---- overall_status (deterministic, live sources) ----
let overall = 'healthy';
const reasons = [];

if (storage.status === 'available') {
  if (!storage.device_present || !storage.mounted || storage.mode === 'ro' || storage.emergency_ro || storage.healthy !== true) {
    overall = 'critical';
    reasons.push('storage_unhealthy');
  }
}
if (disk_capacity.status === 'available' && disk_capacity.worst_capacity_state === 'critical') {
  overall = 'critical';
  reasons.push('disk_capacity_critical');
}
if (docker.status === 'available' && (docker.critical_problems || []).length > 0) {
  overall = 'critical';
  reasons.push('docker_critical_problem');
}
if (backups.status === 'available' && backups.healthy !== true) {
  const hasCriticalIssue = (backups.issues || []).some((i) => String(i.severity).toLowerCase() === 'critical');
  if (hasCriticalIssue) {
    overall = 'critical';
    reasons.push('backup_critical');
  }
}

if (overall !== 'critical') {
  if (disk_capacity.status === 'available' && ['warning', 'error'].includes(disk_capacity.worst_capacity_state)) {
    overall = 'degraded';
    reasons.push('disk_capacity_' + disk_capacity.worst_capacity_state);
  }
  if (docker.status === 'available' && ((docker.summary?.unhealthy || 0) > 0 || (docker.summary?.restarting || 0) > 0 || (docker.summary?.stopped || 0) > 0 || (docker.problem_containers || []).length > 0)) {
    overall = 'degraded';
    reasons.push('docker_degraded');
  }
  if (backups.status === 'available' && (backups.healthy !== true || (backups.issues || []).length > 0)) {
    overall = 'degraded';
    reasons.push('backup_issues');
  }
  if (postgres.status === 'available' && postgres.ok !== true) {
    overall = 'degraded';
    reasons.push('postgres_not_ok');
  }
  // Partial data unavailability degrades, does not go critical alone
  const unavailableLive = [system, storage, disk_capacity, docker, backups].filter((s) => s.status === 'unavailable').length;
  if (unavailableLive > 0) {
    overall = overall === 'healthy' ? 'degraded' : overall;
    reasons.push('partial_source_unavailable');
  }
}

const summaryText =
  overall === 'healthy'
    ? 'OMEAB operando normalmente.'
    : overall === 'degraded'
      ? 'OMEAB operacional com atenção recomendada.'
      : 'OMEAB requer atenção imediata.';

const sources = {
  available: [],
  unavailable: [],
  not_monitored: ['internet'],
};
for (const [k, v] of Object.entries({ system, storage, disk_capacity, docker, backups, services, postgres, events })) {
  if (v.status === 'available') sources.available.push(k);
  else if (v.status === 'unavailable') sources.unavailable.push(k);
}

const snapshot = {
  report_type: 'daily_omeab',
  generated_at: toIso,
  period: { from, to: toIso },
  overall_status: overall,
  overall_reasons: reasons,
  summary: summaryText,
  system,
  storage,
  disk_capacity,
  docker,
  backups,
  services,
  postgres,
  internet,
  events,
  sources,
};

return [{ json: { snapshot } }];

const snap = $json.snapshot;
const icon = { healthy: '🟢', degraded: '🟡', critical: '🔴' };
const o = snap.overall_status || 'healthy';

function lineOrWarn(ok, okText, warnText) {
  return ok ? okText : warnText;
}

const sys = snap.system;
const storage = snap.storage;
const disk = snap.disk_capacity;
const docker = snap.docker;
const backups = snap.backups;
const postgres = snap.postgres;
const events = snap.events;
const internet = snap.internet;

const lines = [];
lines.push('🏠 OMEAB — Resumo diário');
lines.push('');

// Server
lines.push('🖥 Servidor');
if (sys.status === 'available') {
  lines.push(`${icon.healthy} Online há ${sys.uptime_human || '?'}`);
  lines.push(`CPU: ${sys.cpu_percent ?? '?'}%`);
  lines.push(`RAM: ${sys.ram_percent ?? '?'}%`);
  if (sys.load_1m != null) lines.push(`Load: ${sys.load_1m} / ${sys.load_5m} / ${sys.load_15m}`);
} else {
  lines.push('⚠️ Dados de sistema indisponíveis');
}
lines.push('');

// Storage + disk
lines.push('💾 Armazenamento');
if (storage.status === 'available') {
  const stIcon = storage.healthy && storage.mounted && storage.mode === 'rw' ? icon.healthy : icon.critical;
  lines.push(`${stIcon} RAID ${storage.mounted ? 'montado' : 'NÃO montado'} ${String(storage.mode || '').toUpperCase()}`);
} else {
  lines.push('⚠️ Storage: dados indisponíveis');
}
if (disk.status === 'available') {
  for (const fs of disk.filesystems || []) {
    const mark = fs.capacity_state === 'normal' ? icon.healthy : fs.capacity_state === 'warning' ? '🟡' : '🔴';
    lines.push(`${mark} ${fs.mount}: ${fs.used_percent}% utilizado (${fs.free_gb} GB livres)`);
  }
} else {
  lines.push('⚠️ Capacidade de disco: dados indisponíveis');
}
lines.push('');

// Docker
lines.push('🐳 Docker');
if (docker.status === 'available') {
  const s = docker.summary || {};
  const dIcon = docker.healthy && (s.stopped || 0) === 0 && (s.unhealthy || 0) === 0 ? icon.healthy : icon.degraded;
  lines.push(`${dIcon} ${s.running ?? '?'}/${s.total ?? '?'} containers operacionais`);
  lines.push(`Unhealthy: ${s.unhealthy ?? 0}`);
  lines.push(`Restarting: ${s.restarting ?? 0}`);
} else {
  lines.push('⚠️ Dados indisponíveis');
}
lines.push('');

// Backup
lines.push('💾 Backup');
if (backups.status === 'available') {
  const bIcon = backups.healthy ? icon.healthy : icon.degraded;
  const resticAt = backups.restic?.last_backup_at || backups.restic?.last_snapshot_at || 'n/d';
  lines.push(`${bIcon} ${backups.healthy ? 'Backup atualizado' : 'Backup com pendências'}`);
  lines.push(`Último Restic: ${resticAt}`);
  if ((backups.issues || []).length) {
    for (const issue of backups.issues.slice(0, 3)) {
      lines.push(`• ${issue.message || issue.code || 'issue'}`);
    }
  }
} else {
  lines.push('⚠️ Dados indisponíveis');
}
lines.push('');

// Postgres
lines.push('🗄 PostgreSQL');
if (postgres.status === 'available') {
  lines.push(`${postgres.ok ? icon.healthy : icon.degraded} ${postgres.ok ? 'Online' : `Estado: ${postgres.state}/${postgres.health}`}`);
} else {
  lines.push('⚠️ Dados indisponíveis');
}
lines.push('');

// Internet
lines.push('🌐 Internet');
lines.push('⚪ Não monitorado neste relatório');
lines.push('');

// Events
lines.push('📋 Últimas 24h');
if (events.status === 'available') {
  lines.push(`• ${events.critical} CRITICAL`);
  lines.push(`• ${events.error} ERROR`);
  lines.push(`• ${events.warning} WARNING`);
  lines.push(`• ${events.info} INFO`);
  lines.push(`• ${events.requires_attention} requerem atenção`);
  if ((events.top_events || []).length) {
    lines.push('Destaques:');
    for (const ev of events.top_events.slice(0, 5)) {
      lines.push(`• [${String(ev.severity || '').toUpperCase()}] ${ev.event}: ${String(ev.message || '').slice(0, 90)}`);
    }
  }
} else {
  lines.push('⚠️ Eventos indisponíveis');
}
lines.push('');
lines.push(`Estado geral: ${o.toUpperCase()}`);
lines.push(`Resumo: "${snap.summary}"`);
lines.push('');
lines.push('— Hestia / OMEAB Daily Report');

const text = lines.join('\n');

return [{
  json: {
    snapshot: snap,
    alert: {
      type: 'HESTIA_DAILY_REPORT',
      priority: o === 'critical' ? 'high' : 'normal',
      text,
    },
  },
}];

const crypto = require('crypto');

const event = $json;
const secret = $env.HESTIA_WEBHOOK_SECRET;

if (!secret) {
  throw new Error('HESTIA_WEBHOOK_SECRET não está disponível no ambiente do n8n.');
}

// Reutiliza rota hestia-alerts (deliver_only=true):
// o texto formatado É a mensagem Telegram. Snapshot estruturado fica no workflow.
const body = JSON.stringify({
  alert: {
    text: event.alert.text,
  },
});

const timestamp = String(Math.floor(Date.now() / 1000));
const canonicalPayload = `${timestamp}.${body}`;
const signature = crypto
  .createHmac('sha256', secret)
  .update(canonicalPayload, 'utf8')
  .digest('hex');

return [{
  json: {
    ...event,
    hermes_request: {
      body,
      timestamp,
      signature,
      body_bytes: Buffer.byteLength(body, 'utf8'),
    },
  },
}];
